-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.deck_settings (
  user_id uuid default auth.uid() not null,
  deck_id text not null,
  preset_id uuid,
  author_preset text,
  updated_at timestamp with time zone default now() not null,
  constraint deck_settings_pkey PRIMARY KEY (user_id, deck_id),
  constraint deck_settings_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint deck_settings_user_id_preset_id_fkey FOREIGN KEY (user_id, preset_id) REFERENCES public.user_presets(user_id, id) ON DELETE CASCADE,
  constraint deck_settings_author_preset_check CHECK (((char_length(author_preset) >= 1) AND (char_length(author_preset) <= 200))),
  constraint deck_settings_check CHECK (((preset_id IS NULL) <> (author_preset IS NULL))),
  constraint deck_settings_deck_id_check CHECK ((deck_id ~ '^[0-9]{1,20}$'::text))
);

CREATE TRIGGER quota_rows AFTER INSERT ON public.deck_settings FOR EACH ROW EXECUTE FUNCTION public.quota_rows('5000');

alter table public.deck_settings enable row level security;

create policy "own deck settings" on public.deck_settings
  as permissive
  for all
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)))
  with check (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant delete, insert, select, update on table public.deck_settings to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.deck_settings to service_role;
